import React, { useEffect, useState } from "react";
import logo from "../assets/logo.jpeg"; // Adjust path if needed

const WorkerSplash = ({ onComplete }) => {
  const [phase, setPhase] = useState("init"); // init, drive, zoom

  useEffect(() => {
    // Stage 1: Initial fade in
    setTimeout(() => setPhase("drive"), 500);
    // Stage 2: The Netflix "Zoom into screen"
    setTimeout(() => setPhase("zoom"), 2500);
    // Finish
    setTimeout(onComplete, 3800);
  }, [onComplete]);

  return (
    <div className="h-screen bg-[#0F172A] flex items-center justify-center overflow-hidden relative">
      {/* Cinematic Vignette */}
      <div className="absolute inset-0 bg-radial-gradient from-transparent to-black opacity-80 z-10" />

      {/* The Animated Logo Container */}
      <div className={`relative z-20 transition-all duration-1000 
        ${phase === "zoom" ? "animate-truck-entrance" : "scale-100"}
        ${phase === "drive" ? "animate-rumble" : ""}
      `}>

        {/* Glow behind the truck */}
        <div className="absolute inset-0 bg-[#CAD23C] blur-[100px] opacity-20 scale-150 animate-pulse" />

        <img 
          src={logo} 
          alt="T2T Truck" 
          className="w-80 md:w-[500px] h-auto object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.5)]"
        />

        {/* Tactical Slogan Overlay */}
        {phase !== "zoom" && (
          <div className="mt-8 text-center animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-500">
            <h1 className="text-white font-[1000] italic text-4xl tracking-tighter uppercase">
              T2T <span className="text-[#CAD23C]">WORKER_OS</span>
            </h1>
            <p className="text-[#CAD23C] font-black text-[10px] tracking-[0.6em] mt-2 opacity-60">
              EVERY_JOURNEY_MATTERS
            </p>
          </div>
        )}
      </div>

      {/* Industrial Scanlines */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-30 bg-[length:100%_2px,3px_100%]" />
    </div>
  );
};

export default WorkerSplash;
